//! Renders `java/native/src/generated.rs` — the JNI forwarders.

use crate::gen::parse::FfiFn;
use crate::gen::typemap::{is_generatable, map_param, map_type, Kind};

/// JNI symbol mangling: `_` in a Java identifier becomes `_1`.
fn mangle(java_method: &str) -> String {
    java_method.replace('_', "_1")
}

fn banner() -> String {
    "// @generated by `cargo run -p int2dds-java --bin gen-jni`\n\
     // Source of truth: ffi/src/**.rs\n\
     // DO NOT EDIT — regenerate instead. CI fails on drift.\n\n\
     #![allow(\n\
     \x20   non_snake_case,\n\
     \x20   unused_mut,\n\
     \x20   unused_unsafe,\n\
     \x20   unused_variables,\n\
     \x20   clippy::too_many_arguments\n\
     )]\n\n\
     use jni::objects::{JByteArray, JClass, JObjectArray};\n\
     use jni::sys::{jboolean, jdouble, jfloat, jint, jlong};\n\
     use jni::JNIEnv;\n\n"
        .to_string()
}

pub fn emit_rust(fns: &[FfiFn]) -> String {
    let mut out = banner();
    for f in fns.iter().filter(|f| is_generatable(f)) {
        out.push_str(&emit_one(f));
        out.push('\n');
    }
    out
}

fn emit_one(f: &FfiFn) -> String {
    let symbol = format!("Java_com_intellectus_int2dds_internal_ffi_Ffi_{}", mangle(&f.name));

    // `'local` is always declared: `JNIEnv<'local>` uses it even when no object
    // parameter does, so one uniform shape avoids a second code path.
    let mut sig = vec!["mut env: JNIEnv<'local>".to_string(), "_class: JClass<'local>".to_string()];
    for p in &f.params {
        let m = map_type(&p.ty).unwrap();
        sig.push(format!("{}: {}", p.name, m.jni));
    }

    let ret_ty = if f.ret == "()" {
        String::new()
    } else {
        format!(" -> {}", map_type(&f.ret).unwrap().jni)
    };

    // Statements before the call, argument expressions for it, and statements
    // that must run after it (out-parameter write-back).
    let mut pre = String::new();
    let mut post = String::new();
    let mut args = Vec::new();
    for (i, p) in f.params.iter().enumerate() {
        // `map_param` (not `map_type`) so a `*mut [u8; N]` followed by a
        // `capacity` is seen as a caller-sized array, not a single fixed out.
        let m = map_param(&f.params, i).unwrap();
        let n = &p.name;
        match m.kind {
            // `jboolean` is a `u8`; Rust forbids `u8 as bool`, so compare.
            Kind::Scalar if m.jni == "jboolean" => args.push(format!("{n} != 0")),
            // Rust-side widths differ from Java's; cast explicitly.
            Kind::Scalar => args.push(format!("{n} as _")),
            Kind::Pointer => {
                // `jlong` -> `usize` -> raw pointer. Going via `usize` keeps the
                // cast valid on every target; the pointee type infers from the
                // callee's parameter. Preserve the original constness.
                let star = if p.ty.starts_with("*mut ") { "*mut" } else { "*const" };
                args.push(format!("{n} as usize as {star} _"));
            }
            Kind::CStringIn => {
                pre.push_str(&format!(
                    "    let {n}_buf = crate::generated_support::take_bytes(&mut env, &{n});\n"
                ));
                args.push(format!("crate::generated_support::ptr_or_null(&{n}_buf) as _"));
            }
            Kind::CStringOut => {
                pre.push_str(&format!(
                    "    let mut {n}_buf = crate::generated_support::out_buffer(&mut env, &{n});\n"
                ));
                post.push_str(&format!(
                    "    crate::generated_support::write_back_opt(&mut env, &{n}, &{n}_buf);\n"
                ));
                args.push(format!("crate::generated_support::ptr_or_null_mut(&mut {n}_buf) as _"));
            }
            Kind::CStringArray => {
                pre.push_str(&format!(
                    "    let {n}_arr = crate::generated_support::take_string_array(&mut env, &{n});\n"
                ));
                args.push(format!("{n}_arr.as_ptr() as _"));
            }
            Kind::ByteArrayIn => {
                let len = m.len.expect("ByteArrayIn carries its length");
                pre.push_str(&format!(
                    "    let {n}_in = crate::generated_support::take_fixed::<{len}>(&mut env, &{n});\n"
                ));
                args.push(format!("crate::generated_support::fixed_ptr(&{n}_in) as _"));
            }
            Kind::ByteArrayOut => {
                let len = m.len.expect("ByteArrayOut carries its length");
                pre.push_str(&format!("    let mut {n}_out = [0u8; {len}];\n"));
                post.push_str(&format!(
                    "    crate::generated_support::write_back(&mut env, &{n}, &{n}_out);\n"
                ));
                args.push(format!("crate::generated_support::fixed_ptr_mut(&mut {n}_out) as _"));
            }
            Kind::ByteArrayOutSized => {
                let len = m.len.expect("ByteArrayOutSized carries its element length");
                // Caller-sized array: the Java `byte[]` holds `capacity * N`
                // bytes and the FFI writes a variable number of N-byte elements.
                // Size the buffer from the array's ACTUAL length (never a fixed
                // N-byte stack array, which would overflow past the first
                // element), then copy the whole buffer back.
                //
                // Clamp `capacity` to what the buffer actually holds: shadowing
                // the `jlong` parameter here (before the call) turns a caller
                // that overstates capacity into safe truncation rather than a
                // heap overflow, since the core writes up to `capacity * N`
                // bytes. The sibling is always literally named `capacity`
                // (that is why `map_param` fired), so the identifier is in scope.
                pre.push_str(&format!(
                    "    let {n}_len = env.get_array_length(&{n}).unwrap_or(0).max(0) as usize;\n\
                     \x20   let mut {n}_buf = vec![0u8; {n}_len];\n\
                     \x20   let capacity = core::cmp::min(capacity as usize, {n}_len / {len});\n"
                ));
                post.push_str(&format!(
                    "    crate::generated_support::write_back(&mut env, &{n}, &{n}_buf);\n"
                ));
                args.push(format!("{n}_buf.as_mut_ptr() as *mut [u8; {len}] as _"));
            }
        }
    }

    // `usize` returns must be widened to `jlong`; `i32`-shaped returns are
    // already `jint`. A trailing `as _` is correct for both and a no-op cast is
    // harmless. Unit returns take no cast.
    let call = format!("unsafe {{ int2dds_ffi::{}::{}({}) }}", f.module, f.name, args.join(", "));

    // The result is always bound before being cast. `unsafe { .. } as _` does
    // not parse: a block-like expression at the start of a statement is taken
    // as a statement, so the `as` has nothing to apply to. Binding also gives
    // the out-parameter write-back somewhere to run before the return.
    let body = match (post.is_empty(), f.ret == "()") {
        (true, true) => format!("    {call};\n"),
        (true, false) => format!("    let __ret = {call};\n    __ret as _\n"),
        (false, true) => format!("    {call};\n{post}"),
        (false, false) => format!("    let __ret = {call};\n{post}    __ret as _\n"),
    };

    format!(
        "#[no_mangle]\npub extern \"system\" fn {symbol}<'local>(\n    {}\n){ret_ty} {{\n{pre}{body}}}\n",
        sig.join(",\n    ")
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::gen::parse::{FfiFn, Param};

    fn p(name: &str, ty: &str) -> Param {
        Param { name: name.into(), ty: ty.into() }
    }

    fn f(name: &str, module: &str, params: Vec<Param>, ret: &str) -> FfiFn {
        FfiFn { name: name.into(), params, ret: ret.into(), module: module.into() }
    }

    fn write_serialized() -> FfiFn {
        f(
            "int2dds_datawriter_write_serialized",
            "publisher",
            vec![
                p("writer", "*const Int2DdsDataWriter"),
                p("data", "*const u8"),
                p("data_len", "usize"),
                p("key", "*const u8"),
                p("key_len", "usize"),
            ],
            "Int2DdsRet",
        )
    }

    #[test]
    fn emits_a_jni_mangled_symbol_name() {
        let out = emit_rust(&[write_serialized()]);
        assert!(
            out.contains(
                "pub extern \"system\" fn \
                 Java_com_intellectus_int2dds_internal_ffi_Ffi_int2dds_1datawriter_1write_1serialized"
            ),
            "underscores in the Java method name must be escaped as _1:\n{out}"
        );
    }

    #[test]
    fn pointer_params_arrive_as_jlong_and_are_cast() {
        let out = emit_rust(&[write_serialized()]);
        assert!(out.contains("writer: jlong"), "{out}");
        assert!(out.contains("writer as usize as *const _"), "{out}");
    }

    #[test]
    fn forwards_through_the_ffi_module_path() {
        // int2dds-ffi re-exports nothing at its crate root, so an unqualified
        // `int2dds_ffi::<name>` would not resolve.
        let out = emit_rust(&[write_serialized()]);
        assert!(
            out.contains("int2dds_ffi::publisher::int2dds_datawriter_write_serialized"),
            "{out}"
        );
    }

    #[test]
    fn skips_non_generatable_functions() {
        let out = emit_rust(&[f(
            "int2dds_participant_qos_get_properties_with_prefix",
            "qos",
            vec![p("cb", "Option<unsafe extern \"C\" fn () -> i32>")],
            "Int2DdsRet",
        )]);
        assert!(!out.contains("get_1properties_1with_1prefix"), "{out}");
    }

    #[test]
    fn output_starts_with_a_do_not_edit_banner() {
        let out = emit_rust(&[write_serialized()]);
        assert!(out.starts_with("// @generated"), "{out}");
        assert!(out.contains("DO NOT EDIT"));
    }

    #[test]
    fn unit_returning_functions_emit_no_return_type() {
        let out = emit_rust(&[f(
            "int2dds_condition_seq_delete",
            "condition",
            vec![p("seq", "*mut Int2DdsConditionSeq")],
            "()",
        )]);
        assert!(!out.contains("-> jint"), "{out}");
        assert!(out.contains("*mut _"), "constness must be preserved:\n{out}");
    }

    #[test]
    fn absent_c_strings_stay_null() {
        let out = emit_rust(&[f(
            "int2dds_create_participant_with_profile",
            "context",
            vec![p("profile", "*const c_char")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("take_bytes(&mut env, &profile)"), "{out}");
        assert!(
            out.contains("ptr_or_null(&profile_buf)"),
            "a null byte[] must reach the FFI as a null pointer, not \"\":\n{out}"
        );
    }

    #[test]
    fn out_byte_arrays_are_copied_back_to_java() {
        // Without the write-back the FFI's result lands in a Rust-owned buffer
        // and the Java caller's array is never touched.
        let out = emit_rust(&[f(
            "int2dds_datawriter_get_instance_handle",
            "publisher",
            vec![p("writer", "*const Int2DdsDataWriter"), p("handle_out", "*mut [u8; 16]")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("let mut handle_out_out = [0u8; 16];"), "{out}");
        assert!(out.contains("write_back(&mut env, &handle_out, &handle_out_out)"), "{out}");
        // The return value must survive the write-back.
        assert!(out.contains("let __ret = unsafe"), "{out}");
    }

    #[test]
    fn sized_out_byte_arrays_use_a_heap_buffer_not_a_stack_array() {
        // A `*mut [u8; N]` followed by a `capacity` is a caller-sized array. It
        // must be backed by a Vec sized from the Java array, never a fixed
        // `[0u8; N]` stack array, which the FFI overflows past the first element.
        let out = emit_rust(&[f(
            "int2dds_participant_get_discovered_participants",
            "discovery",
            vec![
                p("participant", "*const Int2DdsParticipant"),
                p("handles_out", "*mut [u8; 16]"),
                p("capacity", "usize"),
                p("count_out", "*mut usize"),
            ],
            "Int2DdsRet",
        )]);
        assert!(out.contains("let mut handles_out_buf = vec![0u8; handles_out_len];"), "{out}");
        assert!(out.contains("get_array_length(&handles_out)"), "{out}");
        assert!(
            !out.contains("let mut handles_out_out = [0u8; 16];"),
            "a caller-sized array must not use a fixed stack buffer:\n{out}"
        );
        assert!(out.contains("handles_out_buf.as_mut_ptr() as *mut [u8; 16]"), "{out}");
        assert!(out.contains("write_back(&mut env, &handles_out, &handles_out_buf)"), "{out}");
        // `capacity` is clamped to what the buffer holds, then forwarded, so a
        // caller that overstates capacity truncates instead of overflowing.
        assert!(
            out.contains("let capacity = core::cmp::min(capacity as usize, handles_out_len / 16);"),
            "{out}"
        );
        assert!(out.contains("capacity as _"), "{out}");
    }

    #[test]
    fn in_byte_arrays_are_size_checked() {
        let out = emit_rust(&[f(
            "int2dds_datawriter_unregister_instance",
            "publisher",
            vec![p("writer", "*const Int2DdsDataWriter"), p("handle", "*const [u8; 16]")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("take_fixed::<16>(&mut env, &handle)"), "{out}");
        assert!(out.contains("fixed_ptr(&handle_in)"), "{out}");
        assert!(!out.contains("write_back"), "an in parameter must not write back:\n{out}");
    }

    #[test]
    fn string_arrays_use_the_owning_helper() {
        let out = emit_rust(&[f(
            "int2dds_publisher_qos_set_partition",
            "qos",
            vec![
                p("qos", "*mut Int2DdsPublisherQos"),
                p("names", "*const *const c_char"),
                p("count", "usize"),
            ],
            "Int2DdsRet",
        )]);
        assert!(out.contains("take_string_array(&mut env, &names)"), "{out}");
        assert!(out.contains("names_arr.as_ptr()"), "{out}");
    }

    #[test]
    fn out_text_buffers_are_copied_back_to_java() {
        // `*mut c_char` looks exactly like the in direction but the FFI writes
        // into it. 12 functions — every get-name and get-last-error call.
        let out = emit_rust(&[f(
            "int2dds_last_error_message",
            "last_error",
            vec![p("buf", "*mut c_char"), p("buf_len", "i32")],
            "i32",
        )]);
        assert!(out.contains("out_buffer(&mut env, &buf)"), "{out}");
        assert!(out.contains("ptr_or_null_mut(&mut buf_buf)"), "{out}");
        assert!(out.contains("write_back_opt(&mut env, &buf, &buf_buf)"), "{out}");
        assert!(out.contains("let __ret = unsafe"), "{out}");
    }

    #[test]
    fn in_c_strings_do_not_write_back() {
        let out = emit_rust(&[f(
            "int2dds_create_topic",
            "topic",
            vec![p("name", "*const c_char")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("take_bytes(&mut env, &name)"), "{out}");
        assert!(!out.contains("write_back"), "{out}");
    }

    #[test]
    fn booleans_are_compared_not_cast() {
        // jboolean is a u8 and Rust forbids `u8 as bool`.
        let out = emit_rust(&[f(
            "int2dds_contentfilteredtopic_set_enabled",
            "topic",
            vec![p("topic", "*mut Int2DdsContentFilteredTopic"), p("enabled", "bool")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("enabled != 0"), "{out}");
    }

    #[test]
    fn the_whole_real_surface_emits_without_panicking() {
        // Every generatable function must render; a panic here means map_type
        // and the emitter disagree about some type.
        let fns = crate::gen::parse::parse_ffi_dir(std::path::Path::new("../../ffi/src")).unwrap();
        let out = emit_rust(&fns);
        let emitted = out.matches("#[no_mangle]").count();
        assert_eq!(
            emitted,
            crate::gen::typemap::generatable_count(&fns),
            "one forwarder per generatable function"
        );
    }
}
